# Review package: 563d348..HEAD

## Commits
2462491 fix: add typographic apostrophe joiner to wordCount

## Files changed
 src/textstats.js       |  2 +-
 test/wordCount.test.js | 29 +++++++++++++++++++++++++++++
 2 files changed, 30 insertions(+), 1 deletion(-)

## Diff
diff --git a/src/textstats.js b/src/textstats.js
index 3512261..3b6e988 100644
--- a/src/textstats.js
+++ b/src/textstats.js
@@ -1,16 +1,16 @@
 // A word is a run of letters or digits (any script), optionally joined to the
 // next run by a single apostrophe (straight or typographic) or hyphen. The
 // joiners are only part of a word when letters or digits sit on both sides, so
 // a trailing "well-" or "dogs'" loses its joiner. Everything else, including
 // em dashes, periods and underscores, separates words.
-const WORD_PATTERN = /[\p{L}\p{N}]+(?:[''-][\p{L}\p{N}]+)*/gu;
+const WORD_PATTERN = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu;

 function assertText(fn, value) {
   if (typeof value !== 'string') {
     throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
   }
 }

 // Private: the single definition of "word" shared by every statistic below.
 function tokenize(text) {
   return text.match(WORD_PATTERN) ?? [];
diff --git a/test/wordCount.test.js b/test/wordCount.test.js
index 2dd0579..0971240 100644
--- a/test/wordCount.test.js
+++ b/test/wordCount.test.js
@@ -60,10 +60,39 @@ test('throws a TypeError naming the function for a non-string', () => {

 test('counts the reference passage the same as wc -w', () => {
   assert.equal(wordCount(PASSAGE), 64);
 });

 test('matches every row of the reference table', () => {
   for (const [text, expected] of CASES) {
     assert.equal(wordCount(text), expected, JSON.stringify(text));
   }
 });
+
+test('joins words with straight apostrophe', () => {
+  assert.equal(wordCount("don't"), 1);
+});
+
+test('joins words with typographic apostrophe', () => {
+  // U+2019 right single quotation mark (typographic apostrophe)
+  assert.equal(wordCount('keeper’s'), 1);
+});
+
+test('joins words with hyphen', () => {
+  assert.equal(wordCount('well-known'), 1);
+});
+
+test('drops trailing hyphen', () => {
+  assert.equal(wordCount('well-'), 1);
+});
+
+test('drops trailing apostrophe', () => {
+  assert.equal(wordCount("dogs'"), 1);
+});
+
+test('period separates words in decimal numbers', () => {
+  assert.equal(wordCount('3.14'), 2);
+});
+
+test('period separates domain components', () => {
+  assert.equal(wordCount('example.com'), 2);
+});

